// TideSQLLexerInit initializes any static state used to implement TideSQLLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewTideSQLLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func TideSQLLexerInit() {
	staticData := &TideSQLLexerLexerStaticData
	staticData.once.Do(tidesqllexerLexerInit)
}

// NewTideSQLLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewTideSQLLexer(input antlr.CharStream) *TideSQLLexer {
	TideSQLLexerInit()
	l := new(TideSQLLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &TideSQLLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "TideSQL.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

